// --- DEFINING CONSTANTS --- //
#define SCREEN_W 320
#define SCREEN_H 240
#define KEY_BASE 0xFF200050
#define SW_BASE 0xFF200040
#define PS2_BASE 0xFF200100
#define LED_BASE 0xFF200000

// Window boundaries
#define WINDOW_START_X 24
#define WINDOW_END_X 294
#define WINDOW_START_Y 39
#define WINDOW_END_Y 175

// Player drawing parameters
#define DEFAULT_PLAYER_RADIUS 15
#define DEFAULT_SHOOT_RADIUS 7
int MAX_AMMO = 1000;
int AMMO_RECHARGE = 5;

// --- GLOBAL VARIABLES --- //
volatile bool gameEnd = false;
volatile bool eventFlag = false;
volatile int restart_flag = 0;

volatile int roundNumber = 0;
volatile int player1totalscore = 0;
volatile int player2totalscore = 0;

volatile int pixel_buffer_start;
short int Buffer1[240][512];  // 240 rows, 512 (320 + padding) columns
short int Buffer2[240][512];

volatile int* LEDR_ptr = (int*)0xFF200000;
volatile int* HEX3_HEX0_ptr = (int*)0xFF200020;
volatile int* HEX5_HEX4_ptr = (int*)0xFF200030;
char bit_codes[] = {0x3f, 0x06, 0x5b, 0x4f, 0x66, 0x6d, 0x7d, 0x07, 0x7f, 0x67};

// audio global variables 
int beepFlag3 = 0; 
int beepFlag2 = 0; 
int beepFlag1 = 0; 
int beepFlag0 = 0; 

int beepSignal = 0; // whether or not a beep is triggered 
int lowBeepSignal = 0; // then determine if a low or high beep should be triggered
int highBeepSignal = 0; 
int beepSamplesLeft = 0; 
int beepSampleIndex = 0;

// --- STRUCTS --- //
struct player {
  int x;
  int y;
  int old_x;
  int old_y;

  int dx;
  int dy;
  int colour;
  int paint_colour;

  int score;

  int player_radius;
  int shoot_radius;

  int ammo;
  int is_shooting;

  bool left;
};

