// Random Events
void clearPaintEvent(short* back_buf_ptr);

// Area calculation
void draw_digit(int x, int y, int digit, short color, short* buf);
void displayScore(struct player* p1, struct player* p2, short* back_buf_ptr);
void calculateArea(struct player* p);

void read_ps2key(struct player* p1, struct player* p2, short* back_buf_ptr);
void restart(short* back_buf_ptr, struct player* p1, struct player* p2);

// --- DRAWING FUNCTIONS --- //
// Plot single pixel
void plot_pixel(int x, int y, short int line_colour, short* back_buf_ptr) {
  volatile short int* one_pixel_address;
  // y << 9 is because it is padded
  one_pixel_address = back_buf_ptr + (y << 9) + x;
  *one_pixel_address = line_colour;
}

// Double buffering sync
void wait_for_vsync(void) {
  volatile int* pixel_ctrl_ptr = (int*)0xFF203020;
  volatile int* status_ptr = pixel_ctrl_ptr + 3;

  *pixel_ctrl_ptr =
      1;  // write 1 to Buffer register (offset +0) to trigger swap

  while ((*status_ptr & 0x1) != 0);
}

// Draw background
void draw_background(short* back_buf_ptr) {
  for (int y = 0; y < SCREEN_H; y++) {
    for (int x = 0; x < SCREEN_W; x++) {
      plot_pixel(x, y, background[y * SCREEN_W + x], back_buf_ptr);
    }
  }
}

// Draw progress bar
// The progress goes from 77 to 242, 242 - 77 = 165
volatile double progressx = 77;

void updateProgressBar(short* back_buf_ptr) {
  if (progressx < 242) {
    for (int y = 0; y < 10; y++) {
      plot_pixel(progressx, 194 + y, 0x3130, back_buf_ptr);
    }
  }
}

// --- PLAYER FUNCTIONS --- //
void update_player_position(struct player* p) {
  // shoot timer decreaser
  if (p->is_shooting > 0){p->is_shooting--;}
  if (p->ammo<MAX_AMMO){p->ammo += AMMO_RECHARGE;}

  // Save old position before updating
  p->old_x = p->x;
  p->old_y = p->y;

  p->x += p->dx;
  p->y += p->dy;

  // Clamp position to window bounds
  if (p->x < WINDOW_START_X) {
    p->x = WINDOW_START_X;
  } else if (p->x > WINDOW_END_X) {
    p->x = WINDOW_END_X;
  }

  if (p->y < WINDOW_START_Y) {
    p->y = WINDOW_START_Y;
  } else if (p->y > WINDOW_END_Y) {
    p->y = WINDOW_END_Y;
  }
}

void update_player_movement(struct player* p, int new_dx, int new_dy) {
  p->dx = new_dx;
  p->dy = new_dy;
}

void read_keyboard_input(struct player* p) {
  volatile int* key_ptr = (int*)KEY_BASE;
  int key_value = *key_ptr;

  // Check which key is pressed (bits 0-3 represent keys 0-3)
  if (key_value & 0x1) {  // Key 0 pressed - move right
    update_player_movement(p, 1, 0);
  } else if (key_value & 0x2) {  // Key 1 pressed - move left
    update_player_movement(p, -1, 0);
  } else if (key_value & 0x4) {  // Key 2 pressed - move down
    update_player_movement(p, 0, 1);
  } else if (key_value & 0x8) {  // Key 3 pressed - move up
    update_player_movement(p, 0, -1);
  } else {  // No key pressed - stop
    update_player_movement(p, 0, 0);
  }
}

