void draw_sprite(struct player* p, short* back_buf_ptr, const int* sprite_data, int sprite_width, int sprite_height) {
    // Calculate the starting position (top-left corner of sprite)
    // Since p->x, p->y is the bottom-right corner, offset by 10 pixels x and 10 pixels y
    int start_x = p->x - sprite_width + 10;
    int start_y = p->y - sprite_height + 10;
    
    // Iterate through each pixel of the sprite
    for (int row = 0; row < sprite_height; row++) {
        for (int col = 0; col < sprite_width; col++) {
            int sprite_index = row * sprite_width + col;
            int pixel_color = sprite_data[sprite_index];
            
            // Skip white pixels
            if (pixel_color == 0xffff) {
                continue;
            }
            
            // Calculate screen position
            int screen_x = start_x + col;
            int screen_y = start_y + row;
            
            // Plot pixel using safe_plot_pixel
            safe_plot_pixel(screen_x, screen_y, (short)pixel_color, back_buf_ptr);
        }
    }
}

void draw_player_1(struct player* p, short* back_buf_ptr) {
    if (p->is_shooting > 0) {
        if (p->ammo > MAX_AMMO/2) {
            draw_sprite(p, back_buf_ptr, Player1_Shoot_Full, SPRITE_WIDTH, SPRITE_HEIGHT);
        } else {
            draw_sprite(p, back_buf_ptr, Player1_Shoot_Low, SPRITE_WIDTH, SPRITE_HEIGHT);
        }
    } else {
        if (p->ammo > MAX_AMMO/2) {
            draw_sprite(p, back_buf_ptr, Player1_Full, SPRITE_WIDTH, SPRITE_HEIGHT);
        } else {
            draw_sprite(p, back_buf_ptr, Empty, SPRITE_WIDTH, SPRITE_HEIGHT);
        }
    }
}

void draw_player_2(struct player* p, short* back_buf_ptr) {
    if (p->is_shooting > 0) {
        if (p->ammo > MAX_AMMO/2) {
            draw_sprite(p, back_buf_ptr, Player2_Shoot_Full, SPRITE_WIDTH, SPRITE_HEIGHT);
        } else {
            draw_sprite(p, back_buf_ptr, Player2_Shoot_Low, SPRITE_WIDTH, SPRITE_HEIGHT);
        }
    } else {
        if (p->ammo > MAX_AMMO/2) {
            draw_sprite(p, back_buf_ptr, Player2_Full, SPRITE_WIDTH, SPRITE_HEIGHT);
        } else {
            draw_sprite(p, back_buf_ptr, Empty, SPRITE_WIDTH, SPRITE_HEIGHT);
        }
    }
}


